draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // cloud
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2 + 100*Math.cos(t), H/2 - 50*Math.sin(t), 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // tree
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H - 50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H - 50);
  ctx.lineTo(W/2 - 100, H - 150);
  ctx.stroke();

  // bird
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 50*Math.cos(t), H - 150 + 20*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
